  drawsurfacelayers((0,2,5) -- (0,4,5) -- (2,4,5) -- (2,2,5) -- cycle, layers, styles, true);
  drawsurfacelayers((0,2,6) -- (0,5,6) -- (2,5,6) -- (2,2,6) -- cycle, layers, styles, false);
  drawsurfacelayers((0,0,7) -- (0,4,7) -- (2,4,7) -- (2,0,7) -- cycle, layers, styles, true);
}

pen[] colors = {orange, heavycyan};
drawgraph(colors);
[/asy]

This is a representation of $Q_4.$
[/indent]

[b]Inductive Step: $d-1 \Rightarrow d$[/b]

[indent]
We replace each bar from the configuration for $d-1$ with two bars of the same length.

However we extend some depth to these bars in the new dimension by taking the direct product of this graph and the following side view:

[asy]
size(6cm);
import three;
//currentprojection = orthographic(1,0,0);
currentprojection = orthographic(0,1,0);
//currentprojection = orthographic(5,23,2);
//currentprojection = perspective(-4/5,3,1/2);

void drawsurfacelayers (path3 shape, real layers[], pen styles[], bool flipped)
{
  int layer      = flipped ? layers.length-1 : 0;
  int increment  = flipped ? -1 : 1;

  for (int i=0; i < layers.length; ++i)
  {
      draw(surface(shift((layer, 0, layers[i]))*shape), styles[layer]);
      draw(shift((layer, 0, layers[i]))*shape, styles[layer]);
      layer += increment;
  }
}

void drawgraph(pen styles[])
{
  real[] layers = { 0, 0.5 };

  drawsurfacelayers((0,0,0) -- (0,4,0) -- (2,4,0) -- (2,0,0) -- cycle, layers, styles, false);
  drawsurfacelayers((0,2,2) -- (0,5,2) -- (2,5,2) -- (2,2,2) -- cycle, layers, styles, true);
  drawsurfacelayers((0,2,4) -- (0,4,4) -- (2,4,4) -- (2,2,4) -- cycle, layers, styles, false);
  drawsurfacelayers((0,1,6) -- (0,3,6) -- (2,3,6) -- (2,1,6) -- cycle, layers, styles, true);
  draw((1.5, 3, 1) -- (1.5, 3, 1.5), dotted);
  draw((1.5, 3, 3) -- (1.5, 3, 3.5), dotted);
  draw((1.5, 3, 5) -- (1.5, 3, 5.5), dotted);
}

pen[] colors = {heavyred, blue};
drawgraph(colors);
[/asy]

This is a representation of $Q_{1+d}.$
[/indent]


-----

Given the above, I now claim that if $d \ge 2,$ we can achieve 
$$m \ge \dfrac{d^2 + 3d + 2}2.$$

[b]Proof by Induction:[/b]
[indent]
[b]Base Case: $d=2$[/b]
[indent]
[asy]
unitsize(0.0833333333333333333333333333333333inch);

void drawbox (pair position, pair size, pair scaling, pen p)
{
pair other = position + size;
path cube = position--(other.x, position.y)--(other.x, other.y)--(position.x, other.y)--cycle;
fill(xscale(scaling.x)*yscale(scaling.y)*cube, p);
}

void flatcube (pair scaling, pen p)
{
// Row 1
drawbox((2, 2), (2, 2), scaling, p);
drawbox((9, 3), (2, 2), scaling, p);
drawbox((15, 3), (2, 3), scaling, p);
drawbox((23, 1), (2, 4), scaling, p);
// Row 2
drawbox((3, 9), (2, 2), scaling, p);
drawbox((8, 8), (2, 2), scaling, p);
drawbox((16, 7), (2, 3), scaling, p);
drawbox((22, 8), (2, 4), scaling, p);
// Row 3
drawbox((3, 15), (3, 2), scaling, p);
drawbox((7, 16), (3, 2), scaling, p);
drawbox((16, 16), (3, 3), scaling, p);
drawbox((20, 14), (4, 4), scaling, p);
// Row 4
drawbox((1, 23), (4, 2), scaling, p);
drawbox((8, 22), (4, 2), scaling, p);
drawbox((14, 20), (4, 4), scaling, p);
drawbox((22, 22), (4, 4), scaling, p);

}

void drawgrid (pair start, pair end, pair spacing, pen p)
{
for (real x=start.x; x <= end.x; x += spacing.x)
draw((x, start.y)--(x, end.y), p);
for (real y=start.y; y <= end.y; y += spacing.y)
draw((start.x, y)--(end.x, y), p);
}

pen theGreenIAlwaysUse = rgb(0.3,0.7,0.4);
pen theGreyISometimesUse = grey;

drawgrid((-26, -26), (26, 26), (1, 1), theGreyISometimesUse+dotted);

flatcube((1, 1), theGreenIAlwaysUse);
flatcube((-1, 1), theGreenIAlwaysUse);
flatcube((-1, -1), theGreenIAlwaysUse);
flatcube((1, -1), theGreenIAlwaysUse);

[/asy]
Let the length and height of each square in the grid be 2 units.
[/indent]

[b]Inductive Step: $d-1\Rightarrow d$[/b]
[indent]
Take the construction for $d-1.$  Add 4 units of depth to each rectangle into the new dimension, then continue stacking additional rectangles as described in the first part, above. (Note that 4 units gives enough length in each direction to allow subsequent stacking in additional dimensions).

This multiplies the number of rectangles by $2^{d+1}$ for each new dimension $d,$ to achieve 
$$m \ge \frac{d^2+d}2+(d+1)=\frac{d^2+3d+2}2.$$

[/indent]
[/indent]

[quote=]Another graph that I wonder about is the $m$-dimensional hypercube $Q_{m}$.[/quote]

Here is a simpler construction that [url=http://artofproblemsolving.com/community/c382892h1360530p8787987]again[/url] utilizes Gray code, but achieves a better bound of $m \ge d^2.$

For any tuple $\left(i_0, i_1, \ldots, i_{d-1}\right)$ with $0 \le i_j \le 2^d-1 ~ \forall~ j \in \{ 0, 1, \ldots, d-1 \},$ take cubes of side length 2, where each cube is centered at the sum of the vectors
\begin{align*}
\big((d+2)i_0,~ G_{i_0,0},~G_{i_0,1},~&\ldots,~G_{i_0,d-3},~G_{i_0,d-2}\big),\\
\big(G_{i_1,d-2},~ (d+2)i_1,~ G_{i_1,0},~&\ldots,~G_{i_1,d-4},~G_{i_1,d-3}\big), \\
\big(G_{i_2,d-3},~ G_{i_2,d-2},~ (d+2)i_2,~&\ldots,~G_{i_2,d-5},~G_{i_2,d-4}\big), \\
&\vdots \\
\big(G_{i_{d-2},1},~G_{i_{d-2},2},~G_{i_{d-2},3},~&\ldots,~(d+2)i_{d-2},~G_{i_{d-2},0}\big), \\
\big(G_{i_{d-1},0},~G_{i_{d-1},1},~G_{i_{d-1},2},~&\ldots,~G_{i_{d-1},d-2},~(d+2)i_{d-1}\big).
\end{align*}

(Note that there are $2^{d^2}$ such tuples.)

Here is this construction applied to $d=0:$
